from seg2 import *
import random,math
def seatgrid(v,w=860,seed=3):
    r=random.Random(seed); rows=11; cols=20; out=''
    sel={(5,8),(5,9),(5,10)}; held={(3,4),(3,5)}
    sz=30 if v!=3 else 28
    for i in range(rows):
        out+=f'<div class="row" style="gap:8px;justify-content:center;align-items:center;margin-bottom:8px"><span class="m" style="width:20px">{chr(65+i)}</span>'
        for j in range(cols):
            if j in (6,13): out+='<span style="width:24px"></span>'
            st='sel' if (i,j) in sel else 'held' if (i,j) in held else 'sold' if r.random()<.3 else 'ok'
            rad='50%' if v==3 else ('8px' if v==2 else '3px')
            sty={'sel':'background:var(--acc);color:#fff','held':'border:2px solid var(--acc)','sold':'background:#ececec;color:#999','ok':'background:#fff;border:1.5px solid #cfcfcf' if v!=2 else 'background:#eef0f3'}[st]
            out+=f'<span style="width:{sz}px;height:{sz}px;border-radius:{rad};display:flex;align-items:center;justify-content:center;font-size:12px;{sty}">{"×" if st=="sold" else ""}</span>'
        out+='</div>'
    return out
def legend(v):
    return '<div class="row" style="gap:28px;margin-top:20px;justify-content:center">'+''.join(f'<span class="row m" style="gap:8px;align-items:center"><span style="width:16px;height:16px;border-radius:{"50%" if v==3 else "4px"};{s}"></span>{t}</span>' for t,s in [('Available','border:1.5px solid #cfcfcf'),('Selected','background:var(--acc)'),('Held','border:2px solid var(--acc)'),('Sold','background:#ececec')])+'</div>'
def stage(v): return f'<div style="margin:0 auto 28px;width:640px;height:{ "30px" if v!=1 else "2px"};{"border-radius:999px;background:#f0f0f2" if v==2 else "border-top:3px solid var(--acc);border-radius:50% 50% 0 0/100% 100% 0 0;height:36px" if v==3 else "background:#0d0d0d"};text-align:center"><span class="m" style="position:relative;top:{"6px" if v==2 else "-24px" if v==3 else "10px"};background:#fff;padding:0 10px">Stage</span></div>'
def seatmap(v):
    steps='<div class="row" style="gap:28px;margin-bottom:28px">'+''.join(f'<span class="m" style="{"color:#0d0d0d;border-bottom:2px solid var(--acc);padding-bottom:6px" if i==1 else ""}">0{i+1} {n}</span>' for i,n in enumerate(['Event','Seats','Pay','Tickets']))+'</div>'
    m=stage(v)+seatgrid(v)+legend(v)
    return steps+(box(v,m,40) if v!=3 else f'<div style="border-top:1.5px solid #0d0d0d;padding-top:36px">{m}</div>')
def seatsummary(v):
    lines=[('Sec 112 · Row F · 14','$84.00'),('Sec 112 · Row F · 15','$84.00'),('Sec 112 · Row F · 16','$84.00')]
    ls=''.join(f'<div class="row" style="justify-content:space-between;padding:16px 0;border-top:1px solid {"#0d0d0d" if v==3 else "var(--ln)"}"><span style="font-size:16px">{a}</span><span class="m" style="color:#0d0d0d">{b}</span></div>' for a,b in lines)
    inner=f'<div class="row" style="justify-content:space-between;align-items:center"><div class="m">Your selection</div>{tag("Hold 08:42","a")}</div><div class="l" style="font-size:56px;margin:20px 0">3 tickets</div><div class="row" style="gap:16px;align-items:center;margin-bottom:24px"><div class="art" style="width:64px;height:64px;border-radius:{"50%" if v==3 else "12px"};background-image:url({A}a0.jpg)"></div><div><div style="font-weight:500">Summer Stage</div><div class="m">Sat 14 Jun · 20:00</div></div></div>{ls}<div class="row" style="justify-content:space-between;align-items:end;padding-top:20px;border-top:1px solid #0d0d0d"><span class="m">Total</span><span style="font-size:40px;font-weight:300">$252.00</span></div><div class="btn a" style="width:100%;margin-top:24px;height:56px">Continue to checkout</div><div class="m" style="text-align:center;margin-top:14px">Seats held for 8:42</div>'
    pad=f'<div style="width:520px;margin:0 auto">{inner}</div>'
    return box(v,pad,40,'width:600px;margin:0 auto') if v!=1 else f'<div style="width:560px;margin:0 auto;border-top:1px solid #0d0d0d;padding-top:28px">{inner}</div>'
def payform(v):
    F=lambda l,x:f'<div><div class="m lab" style="margin-top:0">{l}</div><div class="in">{x}</div></div>'
    body=f'<div class="m">Contact</div><div class="g" style="grid-template-columns:1fr 1fr;gap:16px;margin:12px 0 32px">{F("Full name","Alex Morgan")}{F("Email","alex@mail.com")}</div><div class="m">Payment</div><div class="g" style="grid-template-columns:1fr 1fr;gap:16px;margin:12px 0 0"><div style="grid-column:span 2">{F("Card number","•••• •••• •••• 4242")}</div>{F("Expiry","08 / 28")}{F("CVC","•••")}</div><div class="btn a" style="margin-top:32px;width:100%;height:56px">Pay $252.00</div><div class="m" style="text-align:center;margin-top:14px">Test card only · no real payment</div>'
    return head(v,'Checkout','Step 3 of 4')+(box(v,body,40) if v==2 else f'<div style="{"border:1.5px solid #0d0d0d;border-radius:24px;padding:40px" if v==3 else ""}">{body}</div>')
