    st=''.join(f'<div style="flex:1;{"border-top:3px solid var(--acc)" if i==0 else "border-top:1px solid #ccc"};padding-top:12px"><span class="m" style="{"color:#0d0d0d" if i==0 else ""}">0{i+1} {s}</span></div>' for i,s in enumerate(steps))
