    if v==1: return f'<div class="g" style="grid-template-columns:300px 1fr;gap:72px"><div><div class="m">Create event</div><div style="margin-top:28px">'+''.join(f'<div style="padding:14px 0;border-top:1px solid #0d0d0d;{"font-weight:600" if i==0 else "color:#888"}">0{i+1} {s}</div>' for i,s in enumerate(steps))+f'</div></div><div>{body}</div></div>'
    return f'<div class="row" style="gap:12px;margin-bottom:12px">{st}</div>{body}'
